SELECT t.id AS trade_id, t.product_id, p.name AS product_name, CASE WHEN t.buyer_member_id = #{memberId} THEN 'BUY' WHEN t.seller_member_id = #{memberId} THEN 'SELL' END AS type, t.price, t.quantity, (t.price * t.quantity) AS total_amount, t.traded_at FROM trades t JOIN products p ON t.product_id = p.id WHERE (t.buyer_member_id = #{memberId} OR t.seller_member_id = #{memberId})
AND t.buyer_member_id = #{memberId}
AND t.seller_member_id = #{memberId}
ORDER BY t.traded_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM trades t
WHERE (t.buyer_member_id = #{memberId}
OR t.seller_member_id = #{memberId})



            AND t.buyer_member_id = #{memberId}


            AND t.seller_member_id = #{memberId}
